update ${tableName}
SET

    collaborate_latest_process = 'TO_BE_SCHEDULE',

production_status = '处理中',
    reject_reason = null
where primary_key = #{sellOrderCode}
    and enterprise_code = #{enterpriseCode}
    and production_status = '未处理'
    and delete_flag = false

update ${tableName}
SET

    collaborate_latest_process = 'TO_BE_SCHEDULE',

production_status = '已处理',
    reject_reason = null
where primary_key = #{sellOrderCode}
    and enterprise_code = #{enterpriseCode}
    and (production_status = '未处理' OR production_status = '处理中')
    and delete_flag = false

update ${tableName}
set production_status = '未处理',
    reject_reason = #{rejectReason},
    collaborate_latest_process = NULL
where sell_order_sign = #{batchNumber}
